  if(id==='charlas'){const s=C.stats(rows.flatMap(d=>d.payload.participants));html=summary([['Charlas',rows.length,'Sesiones del historial filtrado'],['Presencias',s.present,`${s.total} convocatorias acumuladas`],['Ausencias',s.absent,'En las sesiones filtradas'],['Asistencia',s.total?s.percent+' %':'—','Presencias / convocatorias']])+`<p class="safety-muted">Cada convocatoria corresponde a una persona en una charla. Una persona puede figurar en varias sesiones; la asistencia no acredita por sí sola la participación.</p>`;}
