  html+=`<div class="safety-card"><div class="safety-card-heading"><h2>${id==='vehiculos'?'Historial de inspecciones':'Historial de charlas'}</h2><span class="safety-chip">${rows.length} registro(s)</span></div><div class="safety-table-wrap" tabindex="0" aria-label="Historial, tabla desplazable"><table class="safety-table"><thead><tr><th scope="col">Fecha / responsable</th><th scope="col">${id==='vehiculos'?'Vehículo / resultado':'Tema / asistencia'}</th><th scope="col">Correo</th><th scope="col">Acciones</th></tr></thead><tbody>${rows.map(d=>{const p=d.payload,s=id==='charlas'?C.stats(p.participants):null,j=jobs.get(d.id+':'+d.revision);return `<tr><td>${id==='charlas'?h(p.date+' '+p.time):h(p.reliper?.date?p.reliper.date+' '+p.reliper.time:stamp(d.created_at))}<br><small>${h(d.actor)} · v${d.revision}</small></td><td>${id==='vehiculos'?h(p.vehicle?.plate)+' · '+h(C.aptitude(p,cache.defects.filter(x=>x.vehicle_id===p.vehicleId))):`<strong>${h(p.topic)}</strong><br><small>${h(p.area)}</small><br>${s.present} presentes · ${s.absent} ausentes · ${s.percent} %`}</td><td><span class="safety-chip ${j?.status==='uncertain'?'safety-warning':''}">${h(mailLabels[j?.status]||'Sin reporte')}</span><br><small>${h(j?.error||'')}</small></td><td><div class="safety-row-actions">${button('view','Ver / versiones',d.id)}${button('pdf','PDF',d.id)}${editable()?button('edit','Corregir',d.id):''}${['retry','pending'].includes(j?.status)?button('retry','Procesar correo',d.id):''}</div></td></tr>`;}).join('')||'<tr><td colspan="4"><div class="safety-empty">No hay registros que coincidan. Ajusta o limpia los filtros para consultar el historial.</div></td></tr>'}</tbody></table></div></div>`;
