 function show(title,html,onSubmit){
  dialog.dataset.saving='false';dialog.innerHTML=`<form id="safety-form"><div class="safety-dialog-heading"><h2 id="safety-title">${h(title)}</h2><button type="button" class="btn btn-light" id="safety-close">Cerrar</button></div><div class="safety-dialog-body">${html}</div><div class="safety-dialog-footer"><p id="safety-form-status" class="safety-status" role="status" aria-live="polite"></p>${onSubmit?'<button class="btn btn-primary" type="submit" id="safety-save">Guardar registro</button>':''}</div></form>`;
  $('safety-close').onclick=()=>dialog.close();if(!dialog.open)dialog.showModal();dialog.scrollTop=0;
  $('safety-form').onsubmit=async e=>{e.preventDefault();if(dialog.dataset.saving==='true')return;const submit=$('safety-save'),close=$('safety-close');activeSubmission={owner:window.SSTCloud?.getUser()?.id};dialog.dataset.saving='true';e.target.setAttribute('aria-busy','true');if(submit){submit.disabled=true;submit.textContent='Guardando…';}close.disabled=true;message('safety-form-status','Guardando registro y evidencias…');try{await onSubmit?.(new FormData(e.target),e.target);}catch(error){message('safety-form-status',error.message+' Los datos del formulario se conservan para corregir o reintentar.',true);}finally{activeSubmission=null;dialog.dataset.saving='false';e.target.setAttribute('aria-busy','false');if(submit){submit.disabled=false;submit.textContent='Guardar registro';}close.disabled=false;}};
  // Native validation can target a field inside a collapsed category.
  $('safety-form').addEventListener('invalid',e=>{let section=e.target.closest('details');while(section){section.open=true;section=section.parentElement.closest('details');}},true);
 }
 async function upload(file){assertSubmission();if(!file?.size)return null;if(file.size>10485760||!['image/jpeg','image/png','image/webp','application/pdf'].includes(file.type))throw new Error('Adjunta JPG, PNG, WebP o PDF de hasta 10 MB.');const path=`${window.SSTCloud.getUser().id}/evidence/${crypto.randomUUID()}`;await result(api().storage.from('sst-safety').upload(path,file,{contentType:file.type,upsert:false}));return path;}
 async function uploadPhoto(file){
  if(file.size>10485760||!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Adjunta una fotografía JPG, PNG o WebP de hasta 10 MB.');
  const bitmap=await createImageBitmap(file),scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.82));if(!blob)throw new Error('No se pudo procesar la fotografía.');return upload(new File([blob],'fotografia.jpg',{type:'image/jpeg'}));
 }
 async function save(kind,id,payload,revision,reason){assertSubmission();C.validate(kind,payload);await result(api().rpc('sst_save_document',{doc_id:id,doc_kind:kind,body:payload,expected_revision:revision,change_reason:reason||'Registro inicial'}));dialog.close();showToast('Registro guardado permanentemente. Reporte en cola de envío.');await load();processReports().catch(e=>{if(active)message(active+'-status','Registro guardado. Correo pendiente: '+e.message,true);});}
 async function processReports(){await result(api().functions.invoke('sst-reports',{body:{}}));await load();}
 function vehicleForm(id){const v=cache.vehicles.find(x=>x.id===id);show(v?'Corregir vehículo':'Registrar vehículo',`<div class="safety-grid">${input('Placa','plate',v?.plate||'','text','required minlength="5" maxlength="15"')}${input('Tipo','type',v?.type||'','text','required maxlength="120"')}${input('Marca','brand',v?.brand||'','text','required maxlength="120"')}${input('Modelo','model',v?.model||'','text','required maxlength="120"')}</div><p class="safety-muted">Las correcciones quedan en el historial. Las inspecciones conservan los datos originales.</p>`,async fd=>{const data={plate:C.plate(fd.get('plate')),type:fd.get('type').trim(),brand:fd.get('brand').trim(),model:fd.get('model').trim()};if(v){const rows=await result(api().from('sst_vehicles').update(data).eq('id',v.id).eq('revision',v.revision).select());if(!rows.length)throw new Error('El vehículo cambió en otro dispositivo. Actualiza.');}else await result(api().from('sst_vehicles').insert({id:crypto.randomUUID(),...data}));dialog.close();await load();});}
