   const payload={vehicleId:p.vehicleId||fd.get('vehicleId'),notes:fd.get('notes'),items:C.checklist.map(c=>({id:c.id,label:c.label,critical:c.critical||fd.has('critical-'+c.id),status:fd.get('status-'+c.id),note:fd.get('note-'+c.id),photo:p.items?.find(i=>i.id===c.id)?.photo||null}))};C.validate('inspection',payload);
